snippet_css:
:root{
  --bg: #120D0A;
  --fg: #F3E9D2;
  --muted: #B9A47C;
  --surface: rgba(255,255,255,.07);
  --border: rgba(232,199,102,.30);
  --accent: #E8C766;
  --accent-fg: #2A0B10;
  --accent-grad: linear-gradient(135deg,#A07C16,#E8C766 50%,#A07C16);
  --radius: 4px;
  --radius-sm: 2px;
  --shadow: 0 16px 40px rgba(0,0,0,.65);
  --btn-shadow: 0 0 0 1px rgba(232,199,102,.5);
  --art-bg: radial-gradient(circle at 50% 35%,#6b1a24,#2a0b10 70%),radial-gradient(420px 360px at 78% 50%,rgba(242,197,124,.18),transparent 70%);
  --media-bg: linear-gradient(160deg,#2a0b10,#5B0F1A);
  --cta-bg: radial-gradient(900px 500px at 70% 10%,#3a1a14,transparent),linear-gradient(#1f1410,#160e0b);
  --input-bg: rgba(255,255,255,.08);
  --ok: #2E7D5B;
  --warn: #C24B4B;
  --font-display: 'Playfair Display','Noto Serif TC',serif;
  --font-body: 'Crimson Pro','Noto Serif TC',serif;
  --font-mono: 'Crimson Pro',ui-monospace,'SFMono-Regular',monospace;
  --focus-ring: var(--accent);
}

